BEGIN;
CREATE TABLE IF NOT EXISTS ng2p_geography_areas (area_id text PRIMARY KEY,area_name text NOT NULL,area_level text NOT NULL,zone_id text NOT NULL,zone_name text NOT NULL,state_id text NOT NULL,state_name text NOT NULL,country_code text NOT NULL,parent_id text NOT NULL);
CREATE OR REPLACE VIEW ng2p_record_geography AS
WITH records AS (
 SELECT 'individual'::text AS record_type,internal_record_id,record_status,country_code,geo_lowest_level_value_id,latitude,longitude,geo_code_hierarchy_json FROM g2p_register_individuals
 UNION ALL
 SELECT 'household'::text AS record_type,internal_record_id,record_status,country_code,geo_lowest_level_value_id,latitude,longitude,geo_code_hierarchy_json FROM g2p_register_households
)
SELECT r.record_type,r.internal_record_id,r.record_status,r.country_code,a.zone_id,a.zone_name,a.state_id,a.state_name,
 CASE WHEN a.area_level='lga' THEN a.area_id END AS lga_id,
 CASE WHEN a.area_level='lga' THEN a.area_name END AS lga_name,
 r.geo_code_hierarchy_json->'nigeriag2p'->>'ward' AS ward,
 COALESCE(a.area_level,'unknown') AS administrative_level,
 CASE WHEN r.latitude BETWEEN -90 AND 90 AND r.longitude BETWEEN -180 AND 180 THEN r.latitude END AS latitude,
 CASE WHEN r.latitude BETWEEN -90 AND 90 AND r.longitude BETWEEN -180 AND 180 THEN r.longitude END AS longitude,
 COALESCE(r.geo_code_hierarchy_json->'nigeriag2p'->>'coordinate_source','registry_unverified') AS coordinate_source,
 false AS coordinate_verified,
 'NigeriaG2P project identifiers, not official P-codes'::text AS code_system
FROM records r LEFT JOIN ng2p_geography_areas a ON a.area_id=r.geo_lowest_level_value_id AND r.country_code IN ('NGA','NG');
CREATE OR REPLACE VIEW ng2p_geography_record_counts AS
SELECT record_type,zone_id,zone_name,state_id,state_name,lga_id,lga_name,administrative_level,
 count(*) AS record_count,count(*) FILTER(WHERE latitude IS NOT NULL AND longitude IS NOT NULL) AS coordinates_present
FROM ng2p_record_geography GROUP BY record_type,zone_id,zone_name,state_id,state_name,lga_id,lga_name,administrative_level;
COMMIT;